\begin{tikzpicture}
\begin{axis}[
    width=0.76\textwidth,
    height=0.48\textwidth,
    xmin=0.5, xmax=2.6,
    ymin=-0.05, ymax=1.35,
    axis lines=middle,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={1,1.5,2},
    ytick={0,0.25,1},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
\addplot[very thick, domain=0.55:2.15, samples=150] {(x-1)^2};
% tangent at x_0=2: y=1+2(x-2)=2x-3, meets the axis at x_1=1.5
\addplot[thick, domain=1.5:2.15, samples=2] {2*x-3};
% tangent at x_1=1.5: y=0.25+(x-1.5)=x-1.25, meets the axis at x_2=1.25
\addplot[thick, domain=1.25:1.7, samples=2] {x-1.25};
\addplot[only marks, mark=*] coordinates {(2,1) (1.5,0.25) (1,0)};
\addplot[only marks, mark=o, thick] coordinates {(1.5,0) (1.25,0)};
\node[anchor=west] at (axis cs:2,1) {\(x_0=2\)};
\node[anchor=east] at (axis cs:1.5,0.5) {\(x_1=1.5\)};
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[width=0.82\textwidth,height=0.56\textwidth,
 xmin=-3,xmax=3,ymin=-4,ymax=4,axis lines=middle,
 xlabel={\(x\)},ylabel={\(N(x)\)},xtick={-2,-1,0,1,2},ytick={-4,-2,2,4},
 grid=both,grid style={line width=.1pt,draw=gray!25}]
\addplot[very thick,domain=-3:-0.08,samples=200] {(x-1/x)/2};
\addplot[very thick,domain=0.08:3,samples=200] {(x-1/x)/2};
\draw[dashed,gray] (axis cs:0,-4)--(axis cs:0,4);
\addplot[only marks,mark=*] coordinates {(1,0)};
\node[anchor=west] at (axis cs:1,0) {\(N(1)=0\)};
\node[anchor=west] at (axis cs:1.3,2.8) {\(N(x)=\frac12(x-1/x)\)};
\draw[->,thick] (axis cs:0.0099505,-2.5)--(axis cs:0.0099505,-3.9);
\node[anchor=west,align=left] at (axis cs:0.25,-2.5) {\(N(0.0099505)\approx-50.2438\)\\below the window};
\end{axis}
\end{tikzpicture}
